appearances.css:
.app{padding:6px;font-size:9px}
.row{gap:3px;margin:4px 0}
h3{font-size:9px;margin:6px 0 3px;letter-spacing:.05em}
button,select{font-size:9px;padding:3px 5px;border-radius:4px}
select{padding:2px 2px}
label.control{display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0;padding:0;border:0;border-radius:0;min-width:0;width:54px;flex:0 0 auto}
label.control span{order:3;hyphens:auto;font-size:7.5px;letter-spacing:-.03em;text-align:center;line-height:1.1;max-width:100%;overflow-wrap:anywhere}
label.control output{order:2;font-size:8px;line-height:1.1;text-align:center;white-space:nowrap}
label.control .kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
label.control .kn svg{width:100%;height:100%}
label.control:has(select){width:auto;min-width:56px;flex:0 1 auto}
label.control select{order:2;width:100%}
.grid{display:flex;flex-wrap:wrap;gap:3px 0;padding:3px;border:1px solid var(--line,#344953);border-radius:5px;margin:3px 0}
.grid:has(> div.control){display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:3px;border:0;padding:0}
div.control{padding:3px;border-radius:5px;gap:2px;min-width:0;overflow:hidden}
div.control > button{padding:3px 2px;font-size:8.5px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
div.control .row{margin:0;gap:2px;flex-wrap:nowrap;justify-content:center}
div.control > label.control{display:inline-grid}
div.control label.control{width:auto;flex:1 1 0}
div.control label.control:has(select){min-width:0;width:auto}
div.control select{padding:2px 0;min-width:0}
.app{min-width:0;overflow:hidden}
div.control label.control span{font-size:8px}
canvas{contain:size}
canvas.xy{height:84px}canvas.smp{height:36px}canvas.scope{height:34px}
.pads{grid-template-columns:repeat(8,minmax(0,1fr));gap:2px}
.pads button{min-height:22px;height:24px;font-size:8px;padding:1px 0;text-align:center;white-space:normal;line-height:1}
input[type=file]{font-size:8px;padding:2px;width:auto;max-width:150px}
p{margin:2px 0;font-size:8px;line-height:1.2}
.row > span{font-size:8px}
